.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  background: rgba(255, 255, 255, 0.97);
  border-bottom: 1px solid #d8e0e8;
  box-shadow: 0 4px 18px rgba(24, 53, 82, 0.08);
  backdrop-filter: blur(12px);
}

.site-header__shell {
  width: min(100% - 40px, 1240px);
  min-height: 96px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.site-header__brand {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  border-radius: 10px;
}

.site-header__brand picture {
  display: flex;
  align-items: center;
}

.site-header__logo {
  display: block;
  width: auto;
  height: 76px;
  object-fit: contain;
}

.site-header__navigation {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 12px;
  min-width: 0;
}

.site-header__home {
  min-height: 44px;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 16px;
  border: 1px solid #b8c7d8;
  border-radius: 10px;
  color: #234e7c;
  background: #ffffff;
  font-weight: 700;
  text-decoration: none;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    color 160ms ease;
}

.site-header__home:hover,
.site-header__home--active {
  color: #ffffff;
  border-color: #234e7c;
  background: #234e7c;
}

.site-header__picker {
  display: grid;
  gap: 4px;
  min-width: min(330px, 44vw);
  color: #41566d;
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.site-header__picker-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.site-header__picker select {
  width: 100%;
  min-height: 44px;
  box-sizing: border-box;
  padding: 9px 38px 9px 12px;
  border: 1px solid #b8c7d8;
  border-radius: 10px;
  color: #1d3045;
  background-color: #ffffff;
  font: inherit;
  font-size: 0.94rem;
  font-weight: 600;
  cursor: pointer;
}

.site-header__brand:focus-visible,
.site-header__home:focus-visible,
.site-header__picker select:focus-visible {
  outline: 3px solid rgba(53, 103, 156, 0.28);
  outline-offset: 3px;
}

@media (max-width: 760px) {
  .site-header__shell {
    width: min(100% - 28px, 1240px);
    min-height: auto;
    padding: 10px 0 12px;
    flex-wrap: wrap;
    gap: 8px 16px;
  }

  .site-header__logo {
    height: 58px;
  }

  .site-header__navigation {
    width: 100%;
    align-items: flex-end;
  }

  .site-header__picker {
    flex: 1 1 230px;
    min-width: 0;
  }
}

@media (max-width: 440px) {
  .site-header__shell {
    width: min(100% - 20px, 1240px);
    padding-top: 8px;
    display: grid;
    grid-template-columns: 54px minmax(0, 1fr);
    align-items: end;
    gap: 10px;
  }

  .site-header__logo {
    width: 54px;
    height: 54px;
  }

  .site-header__navigation {
    width: auto;
    min-width: 0;
    gap: 8px;
  }

  .site-header__home {
    width: 44px;
    padding-inline: 0;
  }

  .site-header__home span {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .site-header__picker-label {
    font-size: 0.7rem;
  }

  .site-header__picker select {
    font-size: 0.86rem;
  }
}

