    fontSize: 10,
  },
  tableColDescHeader: {
    width: "55%",
    borderRightWidth: 1,
    borderRightColor: "#000",
    padding: 6,
    textAlign: "center",
    backgroundColor: "#f0f0f0",
    fontWeight: "bold",
    fontSize: 10,
  },
  tableColQtdeHeader: {
    width: "17.5%",
    borderRightWidth: 1,
    borderRightColor: "#000",
