  return (
    <Document>
      <Page size="A4" style={styles.page}>
        {/* Cabeçalho */}
        <View style={{ marginBottom: 15, textAlign: "center" }}>
          <Text style={{ fontSize: 12, fontWeight: "bold" }}>
