  font-size: 14px;
  font-weight: bold;
}

.special-days-field small {
  min-height: 17px;
  color: #666;
}

.selected-days-list {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-height: 28px;
}

.selected-day {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 7px;
  border: 1px solid #b8cce4;
  border-radius: 4px;
  background-color: #eef5fc;
