              condicionais forem validados.
            </p>
          </div>
          <button type="button" className="primary-button" onClick={preparePdf}>
            Validar e preparar PDF
          </button>

          {errors.length > 0 && (
            <div
              className="validation-summary"
              id="validation-summary"
              role="alert"
            >
              <strong>
                Revise{" "}
                {errors.length === 1
                  ? "este campo"
                  : `estes ${errors.length} pontos`}
                :
              </strong>
              <ul>
                {errors.map((error, index) => (
                  <li key={`${error.field}-${index}`}>{error.message}</li>
                ))}
              </ul>
            </div>
          )}

          {ready && (
            <div className="download-ready" aria-live="polite">
              <div>
                <strong>Validação concluída.</strong>
                <span>Seu PDF está pronto para ser montado e baixado.</span>
              </div>
              <PDFDownloadLink
                className="download-button"
                document={<RecadastramentoPdf data={data} />}
                fileName={`recadastramento-${onlyDigits(data.cpf) || "cmpm"}.pdf`}
              >
                {({ loading }) =>
                  loading ? "Montando PDF..." : "Baixar PDF completo"
                }
              </PDFDownloadLink>
            </div>
          )}
        </section>
      </form>
    </div>
  );
};

